CREATE OR REPLACE FUNCTION public.create_household_invitation(p_household_id uuid, p_role text DEFAULT 'parent'::text, p_expires_hours integer DEFAULT 24)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_token text;
  v_token_hash text;
  v_invitation_id uuid;
  v_expires_at timestamptz;
  v_recent_count integer;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Authentication required';
  end if;


  if p_role not in (
    'parent',
    'caregiver',
    'viewer'
  ) then
    raise exception 'Invalid household role';
  end if;


  if p_expires_hours < 1
     or p_expires_hours > 168 then
    raise exception 'Invitation expiry must be between 1 and 168 hours';
  end if;


  if not private.has_household_role(
    p_household_id,
    array['owner']
  ) then
    raise exception 'Only household owners can create invitations';
  end if;


  select count(*)
  into v_recent_count
  from public.household_invitations
  where household_id = p_household_id
    and created_by_user_id = v_user_id
    and created_at > now() - interval '1 hour';


  if v_recent_count >= 10 then
    raise exception 'Too many invitations created recently';
  end if;


  v_token :=
    encode(
      extensions.gen_random_bytes(32),
      'hex'
    );


  v_token_hash :=
    encode(
      extensions.digest(
        v_token,
        'sha256'
      ),
      'hex'
    );


  v_expires_at :=
    now()
    + make_interval(
        hours => p_expires_hours
      );


  insert into public.household_invitations (
    household_id,
    created_by_user_id,
    role,
    token_hash,
    expires_at
  )
  values (
    p_household_id,
    v_user_id,
    p_role,
    v_token_hash,
    v_expires_at
  )
  returning id
  into v_invitation_id;


  return jsonb_build_object(
    'invitation_id',
    v_invitation_id,
    'household_id',
    p_household_id,
    'role',
    p_role,
    'token',
    v_token,
    'expires_at',
    v_expires_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_household_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_token_hash text;
  v_invitation public.household_invitations%rowtype;
  v_household_name text;
begin
  v_user_id := auth.uid();

  if v_user_id is null then
    raise exception 'Authentication required';
  end if;


  if p_token is null
     or length(trim(p_token)) < 20 then
    raise exception 'Invalid invitation';
  end if;


  v_token_hash :=
    encode(
      extensions.digest(
        trim(p_token),
        'sha256'
      ),
      'hex'
    );


  select *
  into v_invitation
  from public.household_invitations
  where token_hash = v_token_hash
  for update;


  if not found then
    raise exception 'Invalid invitation';
  end if;


  if v_invitation.used_at is not null then
    raise exception 'Invitation has already been used';
  end if;


  if v_invitation.expires_at <= now() then
    raise exception 'Invitation has expired';
  end if;


  if exists (
    select 1
    from public.household_members
    where household_id = v_invitation.household_id
      and user_id = v_user_id
  ) then
    raise exception 'You are already a member of this household';
  end if;


  insert into public.household_members (
    household_id,
    user_id,
    role,
    joined_at
  )
  values (
    v_invitation.household_id,
    v_user_id,
    v_invitation.role,
    now()
  );


  update public.household_invitations
  set
    used_at = now(),
    used_by_user_id = v_user_id
  where id = v_invitation.id;


  select name
  into v_household_name
  from public.households
  where id = v_invitation.household_id;


  return jsonb_build_object(
    'household_id',
    v_invitation.household_id,
    'household_name',
    v_household_name,
    'role',
    v_invitation.role
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_baby_for_household(target_household_id uuid, baby_name text, baby_birth_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  current_user_id uuid := auth.uid();
  normalized_name text := trim(baby_name);
  new_baby_id uuid;
begin
  if current_user_id is null then
    raise exception 'Authentication required';
  end if;

  if target_household_id is null then
    raise exception 'Household is required';
  end if;

  if not exists (
    select 1
    from public.household_members hm
    where hm.household_id = target_household_id
      and hm.user_id = current_user_id
      and hm.role in ('owner', 'parent')
  ) then
    raise exception 'Only household owners and parents can add children';
  end if;

  if normalized_name is null
     or char_length(normalized_name) < 1
     or char_length(normalized_name) > 100 then
    raise exception 'Invalid child name';
  end if;

  if baby_birth_date is not null
     and baby_birth_date > current_date then
    raise exception 'Birth date cannot be in the future';
  end if;

  insert into public.babies (
    name,
    birth_date,
    created_by_user_id
  )
  values (
    normalized_name,
    baby_birth_date,
    current_user_id
  )
  returning id into new_baby_id;

  insert into public.baby_households (
    baby_id,
    household_id
  )
  values (
    new_baby_id,
    target_household_id
  );

  return jsonb_build_object(
    'id', new_baby_id,
    'name', normalized_name,
    'birth_date', baby_birth_date
  );
end;
$function$
